import{_ as a,c as i,o as t,ag as n}from"./chunks/framework.CB_NIqHd.js";const m=JSON.parse('{"title":"AI-Assisted Engineering","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/index.md","filePath":"ai-assisted-engineering/index.md"}'),s={name:"ai-assisted-engineering/index.md"};function r(o,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-assisted-engineering" tabindex="-1">AI-Assisted Engineering <a class="header-anchor" href="#ai-assisted-engineering" aria-label="Permalink to “AI-Assisted Engineering”">​</a></h1><p>Use an assistant throughout development while retaining engineer ownership of scope, security, review and actual evidence. Start with one complete local example and add workflow controls in small batches. Reading generated material does not establish independent capability.</p><ol><li><p><a href="./issue-to-reviewed-change.html">Issue to a Reviewed Local Change</a> — repository instructions, precise contracts, context and a reproduced/fixed retry bug.</p></li><li><p><a href="./verification-and-permissions.html">Verification and Permissions</a> — generated-code review, actual API checks, secret minimization and targeted defect challenges.</p></li><li><p><a href="./local-workflow-and-git.html">Local Workflow and Git</a> — repeatable stages, branches/worktrees, permissions and a factual local handoff.</p></li><li><p><a href="./traceability-and-evaluation.html">Traceability and Evaluation</a> — requirement-to-check matrix, candidate identity, measured workflow outcomes and honest documentation.</p></li></ol><p>The worked case is a disposable study fixture. Learner practice and independent human review remain required. No remote push is permitted by this project&#39;s instructions.</p>',4)])])}const g=a(s,[["render",r]]);export{m as __pageData,g as default};
